prelude:
set -eu
g() { git -c user.name=Fixture -c user.email=fixture@example.invalid -c commit.gpgsign=false -c core.hooksPath=/dev/null "$@"; }
commit_file() { mkdir -p "$(dirname "$1/$2")"; printf '%s\n' "$3" > "$1/$2"; g -C "$1" add -A; g -C "$1" commit -qm "$4"; }
add_worktree() { mkdir -p "$REPO/.claude/worktrees"; g -C "$REPO" worktree add -q "$WT" -b "$BRANCH" origin/main; }
push_branch() { g -C "$REPO" push -q origin "$BRANCH"; }
fixed() { add_worktree; commit_file "$WT" fix.txt fix 'fix: the fix'; push_branch; }
lock_dir() { mkdir -p "$1"; : > "$1/held"; chmod 555 "$1"; }
